    'Speedy Cache: clearing pages' => 'Speedy Cache : vidage des pages',
    'Speedy Cache: clearing pages with scheduled changes' => 'Speedy Cache : vidage des pages avec des changements programmés',
    'Speedy Cache: clearing the CDN' => 'Speedy Cache : vidage du CDN',
